.swb-gallery { width: 100%; box-sizing: border-box; }

.swb-gallery .swb-row {
  display: flex;
  flex-wrap: nowrap;
  gap: 10px;
  width: 100%;
  box-sizing: border-box;
}

.swb-gallery .swb-slot {
  position: relative;
  flex: var(--w, 6) 1 0;
  min-width: 0;
  height: 280px;
  overflow: hidden;
  background: #ece9e3;
  border-radius: 2px;
  cursor: zoom-in;
}

.swb-gallery .swb-slot img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transition: transform .45s ease;
}

.swb-gallery .swb-slot:hover img { transform: scale(1.04); }
.swb-gallery .swb-slot:focus-visible { outline: 2px solid #111; outline-offset: 3px; }

/* ---------- lightbox ---------- */
.swb-lb {
  position: fixed;
  inset: 0;
  z-index: 99999;
  display: none;
  align-items: center;
  justify-content: center;
  background: rgba(17,17,17,.94);
  padding: 24px;
  box-sizing: border-box;
}

.swb-lb.is-open { display: flex; }

.swb-lb img {
  max-width: 100%;
  max-height: 100%;
  width: auto;
  height: auto;
  object-fit: contain;
  user-select: none;
}

.swb-lb button {
  position: absolute;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 44px;
  padding: 0;
  background: rgba(255,255,255,.12);
  color: #fff;
  font-family: inherit;
  font-size: 20px;
  line-height: 1;
  border: 0;
  border-radius: 999px;
  cursor: pointer;
  transition: background .2s ease;
}

.swb-lb button:hover { background: rgba(255,255,255,.25); }

.swb-lb .swb-lb-close { top: 18px; right: 18px; font-size: 24px; }
.swb-lb .swb-lb-prev { left: 18px; top: 50%; transform: translateY(-50%); }
.swb-lb .swb-lb-next { right: 18px; top: 50%; transform: translateY(-50%); }

.swb-lb .swb-lb-count {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  color: rgba(255,255,255,.75);
  font-family: "Maison Neue", "Helvetica Neue", Helvetica, Arial, sans-serif;
  font-size: 11px;
  letter-spacing: .12em;
}

body.swb-lb-lock { overflow: hidden; }

/* ---------- mobile: 3 rows of 2, alternating wide / narrow ---------- */
@media (max-width: 900px) {

  .swb-gallery .swb-row {
    flex-wrap: wrap;
    align-items: flex-start;
    column-gap: 2%;
    row-gap: 10px;
    gap: unset;
    column-gap: 2%;
    padding: 0;
    overflow: visible;
  }

  .swb-gallery .swb-slot {
    flex: 0 0 auto;
    height: auto;
    min-width: 0;
  }

  /* row 1 — landscape left, portrait right */
  .swb-gallery .swb-slot:nth-child(1) { width: 63.6%; aspect-ratio: 10 / 9; }
  .swb-gallery .swb-slot:nth-child(2) { width: 34.4%; aspect-ratio: 3 / 5; }

  /* row 2 — portrait left, landscape right */
  .swb-gallery .swb-slot:nth-child(3) { width: 34.4%; aspect-ratio: 3 / 5; }
  .swb-gallery .swb-slot:nth-child(4) { width: 63.6%; aspect-ratio: 10 / 9; }

  /* row 3 — two equal portraits */
  .swb-gallery .swb-slot:nth-child(5) { width: 49%; aspect-ratio: 3 / 5; }
  .swb-gallery .swb-slot:nth-child(6) { width: 49%; aspect-ratio: 3 / 5; }

  .swb-gallery .swb-slot:hover img { transform: none; }

  .swb-lb { padding: 12px; }
  .swb-lb .swb-lb-prev { left: 8px; }
  .swb-lb .swb-lb-next { right: 8px; }
  .swb-lb .swb-lb-close { top: 12px; right: 12px; }
}

@media (max-width: 480px) {
  .swb-gallery .swb-row { padding: 0; row-gap: 8px; }
}

@media (prefers-reduced-motion: reduce) {
  .swb-gallery .swb-slot img { transition: none; }
}

(function () {
  var gallery = document.querySelector('.swb-gallery');
  var lb      = document.querySelector('.swb-lb');
  if (!gallery || !lb) return;

  var slots = [].slice.call(gallery.querySelectorAll('.swb-slot img'));
  var lbImg = lb.querySelector('img');
  var count = lb.querySelector('.swb-lb-count');
  var i = 0;

  function show(n) {
    i = (n + slots.length) % slots.length;
    lbImg.src = slots[i].src;
    lbImg.alt = slots[i].alt || '';
    count.textContent = (i + 1) + ' / ' + slots.length;
  }

  function open(n) {
    show(n);
    lb.classList.add('is-open');
    document.body.classList.add('swb-lb-lock');
  }

  function close() {
    lb.classList.remove('is-open');
    document.body.classList.remove('swb-lb-lock');
    lbImg.src = '';
  }

  slots.forEach(function (img, n) {
    var slot = img.parentNode;
    slot.addEventListener('click', function () { open(n); });
    slot.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); open(n); }
    });
  });

  lb.querySelector('.swb-lb-close').addEventListener('click', close);
  lb.querySelector('.swb-lb-prev').addEventListener('click', function (e) {
    e.stopPropagation(); show(i - 1);
  });
  lb.querySelector('.swb-lb-next').addEventListener('click', function (e) {
    e.stopPropagation(); show(i + 1);
  });

  lb.addEventListener('click', function (e) {
    if (e.target === lb || e.target === lbImg) close();
  });

  document.addEventListener('keydown', function (e) {
    if (!lb.classList.contains('is-open')) return;
    if (e.key === 'Escape')     close();
    if (e.key === 'ArrowLeft')  show(i - 1);
    if (e.key === 'ArrowRight') show(i + 1);
  });

  // swipe on touch devices
  var x0 = null;
  lb.addEventListener('touchstart', function (e) { x0 = e.touches[0].clientX; }, { passive: true });
  lb.addEventListener('touchend', function (e) {
    if (x0 === null) return;
    var dx = e.changedTouches[0].clientX - x0;
    if (Math.abs(dx) > 50) show(dx < 0 ? i + 1 : i - 1);
    x0 = null;
  }, { passive: true });
})();

