  .swbp-examples .swbp-avail-list { font-size: 14px; line-height: 1.5; opacity: .85; }
  .swbp-examples .swbp-avail-list + .swbp-avail-head { margin-top: 6px; }

  /* Card colours */
  .swbp-examples .swbp-t-aqua  { background: var(--aqua);  color: var(--navy);  --line: rgba(11, 42, 74, .25); }
  .swbp-examples .swbp-t-navy  { background: var(--navy);  color: var(--white); --line: rgba(255, 255, 255, .25); }
  .swbp-examples .swbp-t-steel { background: var(--steel); color: var(--white); --line: rgba(255, 255, 255, .25); }
  .swbp-examples .swbp-t-ice   { background: var(--ice);   color: var(--navy);  --line: rgba(11, 42, 74, .2); }

  /* Tablet */
  @media (max-width: 1024px) {
    .swbp-examples .swbp-styles { grid-template-columns: 1fr; }
